package com.nicole.ocean;
/** Forty-five individually named forms, five levels each. */
public final class Evolution {
 public static final int STAGES=56, MAX_LEVEL=55, MAX_ENEMY_LEVEL=56;
 public static final String[] NAMES={"Рыбка-искорка","Русалка","Рифовая акула","Акула-молот","Манта","Дельфин","Косатка","Нарвал","Морской дракон",
 "Рыба-бабочка","Морской конёк","Рыба-луна","Рыба-парусник","Рыба-ангел","Рыба-ёж","Морская черепаха","Аксолотль","Крылатка",
 "Лунный кальмар","Жемчужный краб","Радужная медуза","Листовой дракон","Звёздный скат","Кристальный кит","Коралловый лис","Ленточный угорь","Солнечный наутилус",
 "Снежный пингвин","Ледяной тюлень","Полярный морж","Морской единорог","Сапфировый грифон","Огненный феникс","Рак-богомол","Королевский омар","Глубинный фонарик",
 "Космический осьминог","Хрустальная улитка","Цветочная нимфа","Спиральный аммонит","Грозовой змей","Золотая рыба-комета","Лунная химера","Океанский пегас","Хранительница океана","Коралловая королева","Ледяная саламандра","Изумрудный морской змей","Жемчужная бабочка","Звёздный наутилус","Солнечная медуза","Северный скат","Радужный кит","Золотой феникс","Сердце океана","Древний левиафан"};
 public static int index(int level){return Math.max(0,Math.min(STAGES-1,level-1));}
 public static String name(int level){return NAMES[index(level)];}
}
